//#region globalDataParameters
var globalDataParameters = {
    parameters: [],
    registerParameters: function (system, managerAuth, logger, parameterList) {
        var dfd = $.Deferred();

        var common = require('common')
        var cacheKey = common.getCachePrefix('API', 'GetParameterValue');
        var cacheValue = $.ezstorage.get(cacheKey);

        if (parameterList !== '') {
            if (cacheValue == null) {
                system.log('Main: Loading Config...');
                return $.ajax({
                    type: 'GET',
                    message: "buscando configurações...",
                    messageUser: "Accesso as configurações/parametros do sistema",
                    globalError: true,
                    url: managerAuth.getServiceAddress('LinxFrameworkParametro') + '/GetParameterValue?serializedParameterList=' + parameterList,
                    dataType: 'json',
                    cache: false,
                    error: function (jqXHR, textStatus, errorThrown) {
                        //var msg = 'Error getting the following Parameters: [' + parameterList + ']';
                        //logger.logError(msg, errorThrown, 'GET Fail', true);

                        dfd.resolve();
                    },
                    success: function (data) {
                        var parametersName = '';
                        var parameters = data.split('#');
                        for (var idx in parameters) {
                            var values = parameters[idx].split('|');
                            var pName = values[0];
                            var pValue = values[1];
                            globalDataParameters.parameters[pName] = pValue;
                        }

                        if (managerAuth.isShellDevMode)
                            $.ezstorage.set(cacheKey, data, { expires: 90 })
                        else
                            $.ezstorage.set(cacheKey, data)

                        dfd.promise();
                    }
                });
            }
            else {
                system.log('Main: Loading Config... [Storage]');

                var parametersName = '';
                var parameters = cacheValue.split('#');
                for (var idx in parameters) {
                    var values = parameters[idx].split('|');
                    var pName = values[0];
                    var pValue = values[1];
                    globalDataParameters.parameters[pName] = pValue;
                }

                return dfd.resolve();
            }
        }
    },
    getParameter: function (parameterName, managerAuth, callback) {
        var dfd = $.Deferred();
        return $.ajax({
            type: 'GET',
            message: "buscando parametro...",
            messageUser: "Accesso as configurações/parametros do sistema",
            globalError: true,
            url: managerAuth.getServiceAddress('LinxFrameworkParametro') + '/GetParameterValue?serializedParameterList=' + parameterName,
            dataType: 'json',
            cache: false,
            error: function (jqXHR, textStatus, errorThrown) {
                console.error(errorThrown);
                dfd.resolve();
            },
            success: function (data) {
                var parametersName = '';
                var parameters = data.split('#');
                for (var idx in parameters) {
                    var values = parameters[idx].split('|');
                    if (callback)
                        callback(values[1]);
                }
                dfd.promise();
            }
        });
    }
};
//#endregion globalDataParameters

