            //"html5_assets/js/jqueryui_min.js", 
            //"html5_assets/js/jqueryhelpers_min.js"
            "html5_assets/js/pivot_min.js?" + flexmonster.version,
            "html5_assets/js/file_min.js",
            "html5_assets/js/d3_v3_min.js",
            "html5_assets/js/zlib_min.js",
            "html5_assets/js/jszip_min.js",
            //"html5_assets/js/jspdf_min.js",
            "html5_assets/js/html2canvas_min.js",
            "html5_assets/js/canvg_min.js"
