FlexMonster.prototype.currentLayout = "";
FlexMonster.prototype.prefixNameLayout = "";
FlexMonster.prototype.pivotAdapterLayout = "";

FlexMonster.prototype.getInstanceByPivotName = function (containerId) {
    var instance = null;

    if (FlexmonsterLoader.instances &&
        FlexmonsterLoader.instances.length &&
        FlexmonsterLoader.instances.some(function (item) { return item.containerId == containerId && item._parent })) {

        var instanceFiltered = FlexmonsterLoader
            .instances.filter(function (item) { return item.containerId == containerId && item._parent });

        if (instanceFiltered && instanceFiltered.length)
            instance = instanceFiltered[0]._parent;
    }

    return instance;
};

FlexMonster.prototype.getToolbarInstanceByPivotName = function (containerId) {
    var instance = null;

    if (FlexmonsterLoader.instances &&
        FlexmonsterLoader.instances.length &&
        FlexmonsterLoader.instances.some(function (item) { return item.containerId == containerId && item.toolbar })) {

        var instanceFiltered = FlexmonsterLoader.instances.filter(function (item) { return item.containerId == containerId && item.toolbar });

        if (instanceFiltered && instanceFiltered.length)
            instance = instanceFiltered[0].toolbar;
    }

    return instance;
};

FlexMonster.prototype.saveInServer = function (params) {
    var content = this.getReport();
    var breeze = require('breeze');
    var managerAuth = require('managers/__auth');

    var entity = {
        UId: breeze.core.getUuid(),
        RootNameSpace: params.rootNameSpace,
        ViewName: params.viewName,
        PivotName: params.pivotName,
        PivotDataSource: params.pivotDataSource,
        LayoutName: params.layoutName,
        Selected: params.selected,
        Content: JSON.stringify(content)
    };

    $.ajax({
        async: true,
        cache: false,
        type: 'POST',
        dataType: 'json',
        data: JSON.stringify(entity),
        contentType: 'application/json; charset=UTF-8',
        url: managerAuth.getServiceAddress('linxframeworkobjeto/SavePivotLayout'),
        success: function (data) { flexmonster._alert("Layout salvo com sucesso!"); },
        error: function (errorThrown) { flexmonster._alert("Erro ao salvar o layout: " + errorThrown); }
    });
};

